OverviewKPI.query:
query OverviewKPI($workspaceId: String!, $fromMs: Float!, $toMs: Float!) {
  deckSummary(workspaceId: $workspaceId, fromMs: $fromMs, toMs: $toMs) {
    workspaceId
    deckId
    sessionCount
    viewerCount
    avgSessionMs
    completionRate
  }
}

DeckSummary.query:
query DeckSummary($workspaceId: String!, $deckId: String!, $fromMs: Float!, $toMs: Float!) {
  deckSummary(workspaceId: $workspaceId, deckId: $deckId, fromMs: $fromMs, toMs: $toMs) {
    workspaceId
    deckId
    sessionCount
    viewerCount
    totalEvents
    avgSessionMs
    completionRate
  }
}

SlideBreakdown.query:
query SlideBreakdown($workspaceId: String!, $deckId: String!, $fromMs: Float!, $toMs: Float!) {
  slideBreakdown(workspaceId: $workspaceId, deckId: $deckId, fromMs: $fromMs, toMs: $toMs) {
    slideId
    views
    uniqueViewers
    avgDwellMs
    bounceRate
  }
}

FunnelChart.query:
query FunnelChart($workspaceId: String!, $deckId: String!, $steps: [String!]!, $fromMs: Float!, $toMs: Float!) {
  funnel(workspaceId: $workspaceId, deckId: $deckId, steps: $steps, fromMs: $fromMs, toMs: $toMs) {
    stepName
    entered
    completed
    completionRate
  }
}

HeatmapTile.query:
query HeatmapTile($workspaceId: String!, $deckId: String!, $slideId: String!, $fromMs: Float!, $toMs: Float!) {
  heatmap(workspaceId: $workspaceId, deckId: $deckId, slideId: $slideId, fromMs: $fromMs, toMs: $toMs) {
    workspaceId
    deckId
    slideId
    gridCols
    gridRows
    cells {
      x
      y
      intensity
    }
  }
}

AbTestResults.query:
query AbTestResults($workspaceId: String!, $experimentId: String!) {
  abTestResults(workspaceId: $workspaceId, experimentId: $experimentId) {
    experimentId
    status
    variants {
      variantKey
      exposures
      conversions
      rate
    }
    lift
    pValue
    ciLow
    ciHigh
  }
}

TeamRollup.query:
query TeamRollup($workspaceId: String!) {
  liveSession(sessionId: $workspaceId) {
    sessionId
    concurrentViewers
  }
}

LivePulse.query:
query LivePulse($sessionId: String!) {
  liveSession(sessionId: $sessionId) {
    sessionId
    concurrentViewers
    currentSlide
    recentReactions
    lastEventMs
  }
}
